-- American Classics: 23 recipes
insert into "CozyCookBookSchema".folders (id, name, blurb, user_id, is_public, position) values
  ('00d1c5f5-2c94-5e3f-8d5a-4a30025cfdbe', 'American Classics', 'Diner breakfasts, backyard barbecue and the desserts everyone already knows.', null, true, 0)
on conflict (id) do update set name = excluded.name, blurb = excluded.blurb;

insert into "CozyCookBookSchema".recipes
  (id, title, ingredients, steps, folder_id, user_id, meal, is_public, position)
select r.id, r.title,
  (select coalesce(jsonb_agg(jsonb_build_object('id', gen_random_uuid(), 'name', n, 'isChecked', false) order by o), '[]'::jsonb)
   from unnest(r.ing) with ordinality as t(n, o)),
  (select coalesce(jsonb_agg(jsonb_build_object('id', gen_random_uuid(), 'text', st, 'isChecked', false) order by o), '[]'::jsonb)
   from unnest(r.steps) with ordinality as t(st, o)),
  '00d1c5f5-2c94-5e3f-8d5a-4a30025cfdbe', null, r.meal, true, r.pos
from (values
  ('8e31c7a1-c323-5ea2-a65f-233aee7bc559'::uuid, 'Buttermilk Pancakes', array['2 cups all-purpose flour','2 tbsp granulated sugar','2 tsp baking powder','1 tsp baking soda','1 tsp salt','2 cups buttermilk','2 large eggs','3 tbsp melted butter','Butter and maple syrup to serve'], array['Whisk the dry ingredients in a large bowl.','Beat the buttermilk, eggs and melted butter together.','Fold wet into dry until just combined — lumps are fine, overmixing makes them tough.','Rest the batter 10 minutes while the griddle heats to medium.','Cook 2-3 minutes until bubbles break on the surface, flip, 1-2 minutes more.','Serve immediately with butter and warm syrup.'], 'Breakfast', 0),
  ('a4089c3d-6b02-5476-aefe-08a55c38c488'::uuid, 'Buttermilk Biscuits and Sausage Gravy', array['3 cups all-purpose flour','1 tbsp baking powder','1 tsp salt','3/4 cup cold butter, cubed','1 cup buttermilk','1 lb breakfast sausage','1/4 cup all-purpose flour','3 cups whole milk','1 tsp black pepper'], array['Heat the oven to 450°F.','Cut the cold butter into the flour, baking powder and salt until it looks like coarse gravel.','Stir in buttermilk just until it comes together. Pat to 1 inch, cut rounds, bake 12-15 minutes.','Brown the sausage in a skillet, breaking it up as it cooks.','Sprinkle the flour over the sausage and its fat; cook two minutes.','Whisk in the milk and simmer until thick. Season hard with black pepper.','Split the biscuits and drown them.'], 'Breakfast', 1024),
  ('2f7d7d74-b505-57f4-8617-3f49cd54de05'::uuid, 'Classic Eggs Benedict', array['4 English muffins, split','8 slices Canadian bacon','8 large eggs','3 egg yolks','1 tbsp lemon juice','1 cup melted butter','1 tbsp white vinegar','Pinch of cayenne','Salt to taste'], array['Blend the yolks and lemon juice, then stream in the hot melted butter until the hollandaise thickens. Season and keep warm.','Toast the muffins and warm the Canadian bacon.','Bring water and vinegar to a bare simmer; poach the eggs 3 minutes.','Build: muffin, bacon, egg, hollandaise. Dust with cayenne.'], 'Breakfast', 2048),
  ('7545ac03-72c8-5601-8d4d-fc58425acd2f'::uuid, 'Blueberry Muffins', array['2 cups all-purpose flour','3/4 cup granulated sugar','2 tsp baking powder','1/2 tsp salt','1/2 cup melted butter','1 cup milk','2 large eggs','1 tsp vanilla extract','1 1/2 cups blueberries'], array['Heat the oven to 375°F and line a muffin tin.','Whisk the dry ingredients together.','Combine the butter, milk, eggs and vanilla; fold into the dry until barely mixed.','Toss the blueberries in a spoonful of flour, then fold them in.','Fill the cups high and bake 20-25 minutes until golden.'], 'Breakfast', 3072),
  ('3c27ffb7-dadc-53cc-832e-0a9e356b4694'::uuid, 'Classic Cheeseburger', array['1 lb ground beef','4 burger buns','4 slices cheddar cheese','1 yellow onion, sliced thin','1 tomato, sliced','4 leaves iceberg lettuce','Dill pickles','Salt to taste','Black pepper to taste'], array['Divide the beef into four loose balls — do not compact them.','Get a cast-iron pan screaming hot. Flatten each ball onto it and season.','Sear 2 minutes for a hard crust, flip, add cheese, cook 2 minutes more.','Toast the buns in the rendered fat.','Build and rest one minute before eating.'], 'Lunch', 4096),
  ('b67641cb-33e6-5aca-8e8b-b5190a90e8c6'::uuid, 'BLT Sandwich', array['8 slices bacon','4 slices bread, toasted','2 tomatoes, sliced','4 leaves romaine lettuce','3 tbsp mayonnaise','Black pepper to taste'], array['Cook the bacon until crisp and drain it.','Toast the bread and spread both sides with mayonnaise.','Layer lettuce, tomato, bacon. Pepper the tomato generously.','Cut on the diagonal.'], 'Lunch', 5120),
  ('2ed918b6-1fbc-5497-9ffa-0073acfee1e1'::uuid, 'New England Clam Chowder', array['4 slices bacon, diced','1 yellow onion, diced','2 stalks celery, diced','3 russet potatoes, cubed','2 cans chopped clams with juice','2 cups heavy cream','3 tbsp all-purpose flour','2 fresh thyme sprigs','Salt to taste','Black pepper to taste'], array['Render the bacon; soften the onion and celery in the fat.','Stir in the flour and cook two minutes.','Add the clam juice and potatoes; simmer until the potatoes are tender.','Add the cream and clams and heat through without boiling.','Season and rest 10 minutes before serving — it improves.'], 'Lunch', 6144),
  ('84d23e4b-cc91-5769-bb49-d39ea6922ae0'::uuid, 'Cobb Salad', array['6 cups romaine lettuce, chopped','2 chicken breasts, grilled and sliced','4 slices bacon, crisp','2 hard-boiled eggs, quartered','1 avocado, sliced','1 cup cherry tomatoes, halved','1/2 cup blue cheese crumbles','3 tbsp olive oil','1 tbsp red wine vinegar'], array['Arrange the lettuce on a wide platter.','Lay the toppings in tidy stripes across it.','Whisk the oil and vinegar with salt and pepper.','Dress at the table so nothing wilts.'], 'Lunch', 7168),
  ('9677b3c8-3c73-5525-a287-08b47a9264e4'::uuid, 'Buffalo Chicken Wings', array['2 lbs chicken wings','1 tbsp baking powder','1 tsp salt','1/2 cup hot sauce','1/4 cup butter','1 tbsp honey','Celery sticks to serve'], array['Dry the wings thoroughly and toss with baking powder and salt.','Rest uncovered in the fridge an hour — dry skin is the whole trick.','Bake at 425°F for 45 minutes, turning once.','Melt the butter into the hot sauce and honey.','Toss the wings in the sauce and serve with celery.'], 'Snack', 8192),
  ('0bbca41a-0757-5738-8ced-9d5190151b0d'::uuid, 'Mac and Cheese', array['1 lb elbow macaroni','4 tbsp butter','1/4 cup all-purpose flour','3 cups whole milk','3 cups shredded cheddar cheese','1 tsp mustard powder','1/2 tsp black pepper','1 cup breadcrumbs'], array['Boil the macaroni one minute short of the package time.','Make a roux with the butter and flour; whisk in the milk and simmer until thick.','Off the heat, stir in the cheese, mustard and pepper.','Fold in the pasta, top with breadcrumbs, bake at 375°F for 25 minutes.'], 'Dinner', 9216),
  ('26ec6efd-0053-5469-98c5-ac3bccf1cd72'::uuid, 'Meatloaf with Brown Gravy', array['2 lbs ground beef','1 cup breadcrumbs','1 yellow onion, grated','2 large eggs','1/4 cup ketchup','2 tbsp Worcestershire sauce','1 tsp salt','1 tsp black pepper','2 cups beef stock','2 tbsp all-purpose flour'], array['Mix everything but the stock and flour with your hands, gently.','Shape into a free-form loaf on a sheet pan — a tin steams it.','Bake at 350°F for an hour, glazing with more ketchup at the halfway mark.','Rest 15 minutes. Make gravy from the pan drippings, flour and stock.'], 'Dinner', 10240),
  ('73236e8b-f6ff-50c9-990b-6e1b58baf126'::uuid, 'Southern Fried Chicken', array['1 whole chicken, cut into 8 pieces','2 cups buttermilk','2 tbsp hot sauce','3 cups all-purpose flour','1 tbsp sweet paprika','1 tsp cayenne','2 tsp salt','1 tsp black pepper','Oil for frying'], array['Brine the chicken in buttermilk and hot sauce overnight.','Season the flour heavily — it is the only seasoning the crust gets.','Dredge each piece, pressing hard, and rest 15 minutes so the coating sets.','Fry at 325°F, dark meat 14 minutes, white meat 12, until 165°F inside.','Drain on a rack, never on paper.'], 'Dinner', 11264),
  ('f8d42ce3-1626-5d83-9976-426bb67b1cce'::uuid, 'Pot Roast with Root Vegetables', array['3 lb chuck roast','2 tbsp olive oil','1 yellow onion, quartered','4 carrots, chunked','3 parsnips, chunked','4 russet potatoes, halved','3 cloves garlic, minced','2 cups beef stock','2 fresh rosemary sprigs','Salt to taste','Black pepper to taste'], array['Season and sear the roast hard on every side in a heavy pot.','Remove it, soften the onion and garlic, then deglaze with the stock.','Return the meat, cover, and braise at 300°F for three hours.','Add the root vegetables for the final hour.','The roast is ready when a fork twists out with no resistance.'], 'Dinner', 12288),
  ('3c8945c9-4a8e-58fa-b645-37970fb66c4a'::uuid, 'Grilled Ribeye with Garlic Butter', array['2 ribeye steaks','2 tbsp olive oil','4 cloves garlic, minced','4 tbsp butter','2 fresh thyme sprigs','Salt to taste','Black pepper to taste'], array['Take the steaks out an hour early and salt them.','Sear over the hottest part of the grill, 3 minutes a side.','Move to indirect heat and cook to 130°F for medium-rare.','Rest 10 minutes under garlic-thyme butter.'], 'Dinner', 13312),
  ('135813e4-747d-5233-ae4d-bf62693d6e1c'::uuid, 'Baby Back Ribs', array['2 racks baby back ribs','1/4 cup brown sugar','2 tbsp sweet paprika','1 tbsp salt','1 tbsp black pepper','1 tsp cayenne','1 cup barbecue sauce'], array['Pull the membrane off the bone side — it never softens.','Rub with the sugar and spices and rest an hour.','Bake wrapped in foil at 275°F for 2.5 hours.','Unwrap, sauce, and finish under the broiler until it bubbles and chars at the edges.'], 'Dinner', 14336),
  ('b02ef1dd-ec20-5f42-9fb4-a14eb41a5496'::uuid, 'Thanksgiving Roast Turkey', array['1 whole turkey, 12-14 lbs','1 cup butter, softened','2 yellow onions, quartered','4 stalks celery, chunked','2 lemons, halved','4 fresh sage sprigs','4 fresh thyme sprigs','2 tbsp salt','1 tbsp black pepper'], array['Dry-brine the bird with salt for 24 hours, uncovered, in the fridge.','Work the softened butter under the breast skin.','Stuff the cavity with the aromatics — for flavour, not for eating.','Roast at 425°F for 30 minutes, drop to 325°F for about 2.5 hours.','Pull at 160°F in the breast; it climbs while resting. Rest 30 minutes.'], 'Dinner', 15360),
  ('a8a89ded-ea54-5b76-9993-c9432947dcb8'::uuid, 'Cornbread', array['1 cup cornmeal','1 cup all-purpose flour','1/4 cup granulated sugar','1 tbsp baking powder','1 tsp salt','1 cup buttermilk','2 large eggs','1/3 cup melted butter'], array['Heat a cast-iron skillet with a spoon of butter in a 425°F oven.','Whisk the dry, whisk the wet, combine quickly.','Pour into the hot skillet — the sizzle makes the crust.','Bake 20-25 minutes until the top springs back.'], 'Snack', 16384),
  ('c5f7b826-f731-5ea4-80c9-c1a6b4a43e12'::uuid, 'Coleslaw', array['1 bag coleslaw mix','1/2 cup mayonnaise','2 tbsp apple cider vinegar','1 tbsp granulated sugar','1 tsp celery seed','Salt to taste','Black pepper to taste'], array['Whisk the dressing until the sugar dissolves.','Toss with the cabbage mix.','Chill at least an hour so it slumps and the flavours settle.'], 'Snack', 17408),
  ('57f2c664-4d2f-50ba-8388-611700268bd7'::uuid, 'Apple Pie', array['2 pie crusts','6 Granny Smith apples, sliced','3/4 cup granulated sugar','2 tbsp all-purpose flour','1 tsp cinnamon','1/4 tsp nutmeg','1 tbsp lemon juice','2 tbsp butter','1 egg, beaten'], array['Toss the apples with sugar, flour, spices and lemon; rest 30 minutes and drain the syrup.','Reduce that syrup in a pan until thick and pour it back over the apples — this is what stops a soupy pie.','Fill the crust, dot with butter, lid it, cut vents, brush with egg.','Bake at 425°F for 20 minutes, then 375°F for 40 more.','Cool completely. Cutting it warm will ruin it.'], 'Snack', 18432),
  ('2e233452-4265-5dbd-9a47-9b467e649f8f'::uuid, 'New York Cheesecake', array['2 cups graham cracker crumbs','1/2 cup melted butter','32 oz cream cheese','1 1/2 cups granulated sugar','4 large eggs','1 cup sour cream','2 tsp vanilla extract','1/4 cup all-purpose flour'], array['Press the crumbs and butter into a springform tin and bake 10 minutes at 350°F.','Beat the cream cheese and sugar smooth, then the eggs one at a time on low — air is the enemy.','Fold in the sour cream, vanilla and flour.','Bake in a water bath at 325°F for 90 minutes until the centre still wobbles.','Cool in the switched-off oven with the door ajar, then chill overnight.'], 'Snack', 19456),
  ('f6cc9882-3c31-55a2-bf61-432ac8e2f7ee'::uuid, 'Chocolate Chip Cookies', array['2 1/4 cups all-purpose flour','1 tsp baking soda','1 tsp salt','1 cup butter, softened','3/4 cup granulated sugar','3/4 cup brown sugar','2 large eggs','2 tsp vanilla extract','2 cups chocolate chips'], array['Cream the butter and both sugars until pale and fluffy.','Beat in the eggs and vanilla, then the dry ingredients.','Fold in the chips and chill the dough at least two hours.','Bake at 375°F for 9-11 minutes. Pull them looking underdone.'], 'Snack', 20480),
  ('574447f4-f60a-5ec5-8433-38fac8125bf4'::uuid, 'Brownies', array['1 cup butter','2 cups granulated sugar','4 large eggs','1 cup cocoa powder','1 cup all-purpose flour','1 tsp salt','2 tsp vanilla extract','1 cup chocolate chips'], array['Melt the butter and whisk in the sugar and cocoa while warm.','Beat in the eggs one at a time, hard, for a shiny crust.','Fold in the flour, salt and vanilla, then the chips.','Bake at 350°F for 30 minutes. A few crumbs on the skewer means stop.'], 'Snack', 21504),
  ('99f89487-9e46-528f-8740-64f257e84f9c'::uuid, 'Banana Bread', array['3 ripe bananas, mashed','1/3 cup melted butter','3/4 cup granulated sugar','1 large egg','1 tsp vanilla extract','1 tsp baking soda','Pinch of salt','1 1/2 cups all-purpose flour'], array['Mash the bananas — the blacker the better.','Stir in the butter, sugar, egg and vanilla.','Fold in the soda, salt and flour until just combined.','Bake at 350°F for 55-60 minutes.'], 'Snack', 22528)
) as r(id, title, ing, steps, meal, pos)
on conflict (id) do update set title = excluded.title, ingredients = excluded.ingredients, steps = excluded.steps, meal = excluded.meal;
